			var s = r.domain + ' ' + (r.count || 1);
			if (r.code)
				s += ' @' + r.code;
			(Array.isArray(r.rest) ? r.rest : []).forEach(function (x) { s += ' ' + x; });
			return s.replace(/\s+$/, '');
